-- Messages left by visitors through the portfolio contact form.
-- The id is generated by the browser (one per form), so a retried request cannot insert twice.
CREATE TABLE contact_messages (
    id           UUID          PRIMARY KEY,
    sender_name  VARCHAR(120)  NOT NULL,
    sender_email VARCHAR(254)  NOT NULL,
    reason       VARCHAR(20)   NOT NULL,
    body         VARCHAR(2000) NOT NULL,
    received_at  TIMESTAMPTZ   NOT NULL,
    CONSTRAINT ck_contact_messages_reason
        CHECK (reason IN ('oferta', 'colaboracion', 'consulta', 'otro'))
);

CREATE INDEX ix_contact_messages_received_at ON contact_messages (received_at DESC);

COMMENT ON TABLE contact_messages IS
    'Every row implies the visitor authorised the processing of their data at received_at.';
